package com.cryptoloan.notification.adapters.inout;import com.cryptoloan.notification.application.NotificationService;import com.cryptoloan.notification.domain.model.Notification;import com.cryptoloan.shared.security.AuthenticatedUser;import java.util.List;import org.springframework.http.MediaType;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;@RestController @RequestMapping("/api/notifications")class NotificationController{private final NotificationService service;private final SseNotificationAdapter sse;NotificationController(NotificationService s,SseNotificationAdapter e){service=s;sse=e;}@GetMapping List<Notification>mine(@AuthenticationPrincipal AuthenticatedUser u){return service.mine(u.email());}@GetMapping(value="/stream",produces=MediaType.TEXT_EVENT_STREAM_VALUE)SseEmitter stream(@AuthenticationPrincipal AuthenticatedUser u){return sse.subscribe(u.email());}@PostMapping("/test")Notification test(@AuthenticationPrincipal AuthenticatedUser u){return service.notify(u.email(),"INFO_TEST","Test CryptoLoan","Votre système de notification CryptoLoan fonctionne correctement.",null);}}

